import{_ as n,C as l,o as i,c,j as t,a as o,E as a,a2 as r}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"字体配置与测试界面 (dev.anvilcraft.lib.v2.font.screen)","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.4/font/screens.md","filePath":"1.21.4/font/screens.md"}'),s={name:"1.21.4/font/screens.md"};function g(f,e,p,h,u,b){const d=l("BranchContextCard");return i(),c("div",null,[e[0]||(e[0]=t("h1",{id:"字体配置与测试界面-dev-anvilcraft-lib-v2-font-screen",tabindex:"-1"},[o("字体配置与测试界面 ("),t("code",null,"dev.anvilcraft.lib.v2.font.screen"),o(") "),t("a",{class:"header-anchor",href:"#字体配置与测试界面-dev-anvilcraft-lib-v2-font-screen","aria-label":'Permalink to "字体配置与测试界面 (`dev.anvilcraft.lib.v2.font.screen`)"'},"​")],-1)),a(d,{branch:"1.21.4"}),e[1]||(e[1]=r('<p><code>module.font</code> 内置了可视化客户端字体配置界面 <strong><code>FontConfigScreen</code></strong>、多语言/多样式排版测试界面 <strong><code>FontTestScreen</code></strong>，以及一套带图层点击遮罩（Shielding）的通用下拉选择框组件 <strong><code>Dropdown</code></strong>。</p><p>玩家可以在游戏主菜单点击 <strong>Mods -&gt; AnvilLib Font (<code>anvillib_font</code>) -&gt; Config</strong> 直接打开 <code>FontConfigScreen</code>，从系统已安装的字体族与子字重列表中实时切换并预览 SDF 渲染效果。</p><hr><h2 id="一、-界面与下拉组件-api-详解" tabindex="-1">一、 界面与下拉组件 API 详解 <a class="header-anchor" href="#一、-界面与下拉组件-api-详解" aria-label="Permalink to &quot;一、 界面与下拉组件 API 详解&quot;">​</a></h2><h3 id="_1-fontconfigscreen-与-fonttestscreen-apistatus-internal" tabindex="-1">1. <code>FontConfigScreen</code> 与 <code>FontTestScreen</code> (<code>@ApiStatus.Internal</code>) <a class="header-anchor" href="#_1-fontconfigscreen-与-fonttestscreen-apistatus-internal" aria-label="Permalink to &quot;1. `FontConfigScreen` 与 `FontTestScreen` (`@ApiStatus.Internal`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">类名</th><th style="text-align:left;">构造器签名</th><th style="text-align:left;">功能说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>FontConfigScreen</code></strong></td><td style="text-align:left;"><code>public FontConfigScreen(final ModContainer ignored, final Screen parent)</code></td><td style="text-align:left;">注册在 <code>IConfigScreenFactory</code> 扩展点上的字体配置主界面。提供“字体族（Family）”与“具体字体（Font）”二级联动下拉框，实时用 <code>guiGraphics.anvillib$centeredText</code> 预览当前选中字体，并在每次选择变更时自动持久化到 <code>config/anvillib/anvillib_font-client.json</code>。</td></tr><tr><td style="text-align:left;"><strong><code>FontTestScreen</code></strong></td><td style="text-align:left;"><code>public FontTestScreen(final Screen parent)</code></td><td style="text-align:left;">点击配置页的“Font Test”按钮进入。在同一屏幕内对比展示<strong>原版位图字体 (<code>GuiGraphics#drawString</code>)</strong> 与 <strong>AnvilLib SDF 字体 (<code>GuiGraphics#anvillib$*</code>)</strong> 在纯文本、彩色粗斜体下划线删除线 <code>Component</code>、随机跳变乱码（Obfuscated）、居中文本、带背景框文本以及英文/中文自动折行（Word Wrap）下的渲染表现。</td></tr></tbody></table><hr><h3 id="_2-dropdown-可滚动带遮罩的下拉框控件" tabindex="-1">2. <code>Dropdown</code>（可滚动带遮罩的下拉框控件） <a class="header-anchor" href="#_2-dropdown-可滚动带遮罩的下拉框控件" aria-label="Permalink to &quot;2. `Dropdown`（可滚动带遮罩的下拉框控件）&quot;">​</a></h3><p>位于 <code>dev.anvilcraft.lib.v2.font.screen.widget.Dropdown</code>（标注为 <code>@Beta</code>），继承自 <code>AbstractWidget</code> 并实现 <code>Renderable</code>、<code>GuiEventListener</code>、<code>NarratableEntry</code>。</p><h4 id="关键内部记录与接口" tabindex="-1">关键内部记录与接口 <a class="header-anchor" href="#关键内部记录与接口" aria-label="Permalink to &quot;关键内部记录与接口&quot;">​</a></h4><ul><li><code>Dropdown.DropdownEntry(String id, Component label)</code>：下拉项数据记录，提供静态工厂： <ul><li><code>DropdownEntry.create(String id, Component label)</code></li><li><code>DropdownEntry.create(String id, String label)</code></li></ul></li><li><code>Dropdown.Shielding</code>：当下拉列表展开时，用于拦截下拉列表区域以外底层按钮悬停与点击事件的遮罩层。</li></ul><h4 id="公开构造器与方法" tabindex="-1">公开构造器与方法 <a class="header-anchor" href="#公开构造器与方法" aria-label="Permalink to &quot;公开构造器与方法&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">构造器 / 方法签名</th><th style="text-align:left;">返回值</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public Dropdown(int x, int y, int width, int height, int screenWidth, int screenHeight, Component message)</code><br><code>public Dropdown(int x, int y, int width, int height, int screenWidth, int screenHeight, Component message, List&lt;DropdownEntry&gt; allow)</code></td><td style="text-align:left;"><code>Dropdown</code></td><td style="text-align:left;">创建下拉选择框（弹出列表最大高度为 <code>120px</code>，单行高度 <code>18px</code>，并根据 <code>screenHeight</code> 自动决定向下或向上展开）。</td></tr><tr><td style="text-align:left;"><code>public void setAllow(List&lt;DropdownEntry&gt; allow)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">更新可选条目列表，若当前选中项不在新列表中则自动切换为首项。</td></tr><tr><td style="text-align:left;"><code>public @Nullable DropdownEntry getValue()</code> / <code>public String getValueId()</code></td><td style="text-align:left;"><code>DropdownEntry</code> / <code>String</code></td><td style="text-align:left;">获取当前选中的条目或条目 ID（未选中时 <code>getValueId()</code> 返回 <code>&quot;&quot;</code>）。</td></tr><tr><td style="text-align:left;"><code>public void setValue(@Nullable DropdownEntry value)</code> / <code>public void setValue(@Nullable String id)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">设置当前选中项（若发生变更且已设置 <code>onValueChanged</code> 回调则触发回调）。</td></tr><tr><td style="text-align:left;"><code>public void setOnValueChanged(@Nullable Consumer&lt;@Nullable DropdownEntry&gt; onValueChanged)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">设置选中值变更监听器。</td></tr><tr><td style="text-align:left;"><code>public void setPlaceholder(Component placeholder)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">设置未选中任何条目时的占位提示文本（默认为 <code>&quot;Select...&quot;</code>）。</td></tr><tr><td style="text-align:left;"><code>public void setMaxPopupHeight(int maxPopupHeight)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">设置展开列表的最大像素高度（最小被钳制为单行高度 <code>18px</code>）。</td></tr><tr><td style="text-align:left;"><code>public void setOnShieldingAdd(Consumer&lt;Shielding&gt;)</code><br><code>public void setOnShieldingRemove(Runnable)</code><br><code>public void setShieldingGetter(Supplier&lt;Shielding&gt;)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">绑定父 <code>Screen</code> 的展开遮罩管理回调，防止存在多个下拉框时相互穿透点击。</td></tr></tbody></table>',13))])}const v=n(s,[["render",g]]);export{y as __pageData,v as default};
